    public display int headerPriceAttributeGroupSelectionPriority()
    {
        GUPPriceComponentCodePriceAttributeGroupSelection selection;

        select Priority from selection where
                selection.PriceAttributeGroup == this.HeaderPriceAttributeGroup
                    && selection.PriceComponentCode == this.PriceComponentCode;

        return selection.Priority;
    }

    public display int linePriceAttributeGroupSelectionPriority()
    {
        GUPPriceComponentCodePriceAttributeGroupSelection selection;

        select Priority from selection where
                selection.PriceAttributeGroup == this.LinePriceAttributeGroup
                    && selection.PriceComponentCode == this.PriceComponentCode;

        return selection.Priority;
    }

    internal boolean checkSourceLevel()
    {
        boolean ret = true;

        if (this.HeaderGroupAll == GUPGroupAll::Group && this.HeaderPriceAttributeGroup)
        {
            GUPPricingAttributeGroup headerGroup = GUPPricingAttributeGroup::find(this.HeaderPriceAttributeGroup);
            if (headerGroup.SourceLevel != GUPPricingAttributeSourceLevel::Header)
            {
                ret = checkFailed("@GlobalUnifiedPricing:SourceLevelNotMatchedError");
            }
        }

        if (this.LineGroupAll == GUPGroupAll::Group && this.LinePriceAttributeGroup)
        {
            GUPPricingAttributeGroup lineGroup = GUPPricingAttributeGroup::find(this.LinePriceAttributeGroup);
            if (lineGroup.SourceLevel != GUPPricingAttributeSourceLevel::Line)
            {
                ret = checkFailed("@GlobalUnifiedPricing:SourceLevelNotMatchedError");
            }
        }

        return ret;
    }

    internal boolean checkPriority()
    {
        boolean ret = true;

        if (this.Priority < 0)
        {
            ret = checkFailed("@GlobalUnifiedPricing:CombinationPriorityOutOfRangeError");
        }

        return ret;
    }

    internal boolean checkInvalidAttributeGroup()
    {
        boolean ret = true;

        if ((this.HeaderGroupAll == GUPGroupAll::Group && !this.HeaderPriceAttributeGroup) ||
            (this.HeaderGroupAll == GUPGroupAll::All   &&  this.HeaderPriceAttributeGroup))
        {
            ret = checkFailed("@GlobalUnifiedPricing:GUPPriceComponentCodeCombinationHeaderGroupAllInvalid");
        }

        if ((this.LineGroupAll == GUPGroupAll::Group && !this.LinePriceAttributeGroup) ||
            (this.LineGroupAll == GUPGroupAll::All   &&  this.LinePriceAttributeGroup))
        {
            ret = checkFailed("@GlobalUnifiedPricing:GUPPriceComponentCodeCombinationLineGroupAllInvalid");
        }

        if (this.HeaderGroupAll == GUPGroupAll::Group)
        {
            GUPPricingAttributeGroup attributeGroup = GUPPricingAttributeGroup::find(this.HeaderPriceAttributeGroup);
            if (!attributeGroup.IsValid || attributeGroup.GroupType != GUPPricingAttributeGroupType::General)
            {
                ret = checkFailed("@GlobalUnifiedPricing:GUPPriceComponentCodeCombinationHeaderGroupAllInvalid");
            }
        }

        if (this.LineGroupAll == GUPGroupAll::Group)
        {
            GUPPricingAttributeGroup attributeGroup = GUPPricingAttributeGroup::find(this.LinePriceAttributeGroup);
            if (!attributeGroup.IsValid || attributeGroup.GroupType != GUPPricingAttributeGroupType::General)
            {
                ret = checkFailed("@GlobalUnifiedPricing:GUPPriceComponentCodeCombinationLineGroupAllInvalid");
            }
        }

        return ret;
    }

    internal boolean checkGroupAll()
    {
        boolean ret = true;

        if (this.HeaderGroupAll == GUPGroupAll::All || this.LineGroupAll == GUPGroupAll::All)
        {
            GUPPriceComponentCode priceComponentCode = GUPPriceComponentCode::find(this.PriceComponentCode);

            if (this.HeaderGroupAll == GUPGroupAll::All && priceComponentCode.HeaderPriceAttributeGroupAllEnabled == NoYes::No)
            {
                ret = checkFailed("@GlobalUnifiedPricing:GUPPriceComponentCodeCombinationHeaderAllNotEnabled");
            }

            if (this.LineGroupAll == GUPGroupAll::All && priceComponentCode.LinePriceAttributeGroupAllEnabled == NoYes::No)
            {
                ret = checkFailed("@GlobalUnifiedPricing:GUPPriceComponentCodeCombinationLineAllNotEnabled");
            }
        }

        return ret;
    }

    private boolean checkUsedByPriceDiscTable()
    {
        boolean ret = true;
        PriceDiscTable priceDiscTable;

        select firstonly RecId from priceDiscTable
            where PriceDiscTable.PRICECOMPONENTCOMBINATION == this.RecId
                && PriceDiscTable.PRICECOMPONENTCOMBINATION != 0;

        if (priceDiscTable.RecId != 0)
        {
            GUPPriceComponentCodePriceAttributeGroupCombination combOrig = this.orig();
            if (combOrig.HeaderGroupAll != this.HeaderGroupAll
                || combOrig.LineGroupAll != this.LineGroupAll
                || combOrig.HeaderPriceAttributeGroup != this.HeaderPriceAttributeGroup
                || combOrig.LinePriceAttributeGroup != this.LinePriceAttributeGroup)
            {
                ret = checkFailed("@GlobalUnifiedPricing:CombinationCannotBeUpdated");
            }
        }

        return ret;
    }

    private boolean checkUsedByPriceAdjustmentLine()
    {
        boolean ret = true;
        GUPMarginComponentPriceAdjustmentLine GUPMarginComponentPriceAdjustmentLine;

        select firstonly RecId from GUPMarginComponentPriceAdjustmentLine
            where GUPMarginComponentPriceAdjustmentLine.PriceAttributeGroupCombinationRecId == this.RecId
                && GUPMarginComponentPriceAdjustmentLine.PriceAttributeGroupCombinationRecId != 0;

        if (GUPMarginComponentPriceAdjustmentLine.RecId != 0)
        {
            GUPPriceComponentCodePriceAttributeGroupCombination combOrig = this.orig();
            if (combOrig.HeaderGroupAll != this.HeaderGroupAll
                || combOrig.LineGroupAll != this.LineGroupAll
                || combOrig.HeaderPriceAttributeGroup != this.HeaderPriceAttributeGroup
                || combOrig.LinePriceAttributeGroup != this.LinePriceAttributeGroup)
            {
                ret = checkFailed("@GlobalUnifiedPricing:CombinationCannotBeUpdatedPriceAdjustmentLine");
            }
        }

        return ret;
    }

    public boolean validateWrite()
    {
        boolean ret = super();
    
        ret = ret && this.checkPriority();
        ret = ret && this.checkInvalidAttributeGroup();
        ret = ret && this.checkSourceLevel();
        ret = ret && this.checkGroupAll();
        ret = ret && this.checkUsedByPriceDiscTable();
        ret = ret && this.checkUsedByPriceAdjustmentLine(); 

        return ret;
    }

    public void initPriority(GUPPriceComponentCodePriceAttributeGroupSelection _updatingSelection = null)
    {
        int newPriority = 0;

        if (_updatingSelection && _updatingSelection.SourceLevel == GUPPricingAttributeSourceLevel::Header)
        {
            newPriority += 1000 * _updatingSelection.Priority;
        }
        else if (this.HeaderGroupAll == GUPGroupAll::Group)
        {
            GUPPriceComponentCodePriceAttributeGroupSelection selection;

            select Priority from selection where
                selection.PriceAttributeGroup == this.HeaderPriceAttributeGroup
                    && selection.PriceComponentCode == this.PriceComponentCode;

            newPriority += 1000 * selection.Priority;
        }

        if (_updatingSelection && _updatingSelection.SourceLevel == GUPPricingAttributeSourceLevel::Line)
        {
            newPriority += _updatingSelection.Priority;
        }
        else if (this.LineGroupAll == GUPGroupAll::Group)
        {
            GUPPriceComponentCodePriceAttributeGroupSelection selection;

            select Priority from selection where
                selection.PriceAttributeGroup == this.LinePriceAttributeGroup
                    && selection.PriceComponentCode == this.PriceComponentCode;

            newPriority += selection.Priority;
        }
            
        this.Priority = newPriority;
    }

    public void initName()
    {
        str newCombinationName = this.HeaderGroupAll == GUPGroupAll::Group ? 
                                    GUPPricingAttributeGroup::find(this.HeaderPriceAttributeGroup).Name :
                                    "@GlobalUnifiedPricing:GUPPriceAttributeGroupSelectionAll";

        newCombinationName += '-';


        newCombinationName += this.LineGroupAll == GUPGroupAll::Group ?  
                                GUPPricingAttributeGroup::find(this.LinePriceAttributeGroup).Name :
                                "@GlobalUnifiedPricing:GUPPriceAttributeGroupSelectionAll";
        

        this.Name = newCombinationName;
    }

    public void insert()
    {
        ttsbegin;

        if (GUPPriceComponentCode::find(this.PriceComponentCode).MaintenanceMode == GUPPriceComponentCodeMaintenanceMode::Separate)
        {
            this.initPriority();
            this.initName();
        }

        super();

        ttscommit;
    }

public static str generateUniqueKey(int64 _priceComponentCode, int64 _headerPriceAttributeGroup, int64 _linePriceAttributeGroup)
{
    return int642Str(_priceComponentCode)
        + "_"
        + int642Str(_headerPriceAttributeGroup)
        + "_"
        + int642Str(_linePriceAttributeGroup);
}

public str parmUniqueKey()
{
    return int642Str(this.PriceComponentCode)
        + "_"
        + int642Str(this.HeaderPriceAttributeGroup)
        + "_"
        + int642Str(this.LinePriceAttributeGroup);
}

    public static GUPPriceComponentCodePriceAttributeGroupCombination find(RecId _recId, boolean _update = false)
    {
        GUPPriceComponentCodePriceAttributeGroupCombination  priceAttributeGroupCombination;

        if (_recId)
        {
            priceAttributeGroupCombination.selectForUpdate(_update);

            select firstonly priceAttributeGroupCombination
                where priceAttributeGroupCombination.RecId == _recId;
        }

        return priceAttributeGroupCombination;
    }

public static boolean exist(RecId _recId)
{
    return _recId
        && (select firstonly RecId from GUPPriceComponentCodePriceAttributeGroupCombination
                where GUPPriceComponentCodePriceAttributeGroupCombination.RecId == _recId).RecId;
}
